  add("I1","Isabella Alvarez",1988,"San José, Costa Rica","I2","I3");add("I2","Mateo Alvarez",1961,"Cartago, Costa Rica","I4","I5");add("I3","Sofía Martin",1963,"Madrid, Spain","I6","I7");
