  add("I8","Tomás Alvarez",1902,"Heredia, Costa Rica","I16","I17");add("I9","María Vargas",1907,"San José, Costa Rica");add("I10","Étienne Fournier",1904,"Bordeaux, France");add("I11","Lucía Romano",1909,"Sicily, Italy");add("I12","Diego Martin",1898,"Galicia, Spain");add("I13","Inés Silva",1903,"Porto, Portugal");add("I14","Hiroshi Tanaka",1905,"Osaka, Japan");add("I15","Emi Sato",1911,"Tokyo, Japan");
