function showDetails(slot){selected=slot;if(!slot.id){$("#detailRelation").textContent="Unrecorded branch";$("#detailName").textContent="Unknown ancestor";$("#detailBorn").textContent="Not recorded";$("#detailPlace").textContent="Not recorded";$("#detailMatch").textContent="No person linked to this position";$("#detailColor").style.background=colors.Unknown;$("#originBreakdown").innerHTML='<p class="origin-empty">Not enough recorded birthplace data.</p>';$("#setRoot").hidden=true}else{const p=people[slot.id];$("#detailRelation").textContent=`Generation ${slot.gen+1} · ${slot.relation}`;$("#detailName").textContent=p.name;$("#detailBorn").textContent=p.birthDate||p.year||"Not recorded";$("#detailPlace").textContent=p.place||"Not recorded";$("#detailMatch").textContent=p.confidence;$("#detailColor").style.background=colors[p.country]||colors.Unknown;renderOrigin(slot.id);$("#setRoot").hidden=false}$("#details").classList.add("open");render()}
